import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, applyVoucher, issueInvoice } from '../src/invoices.js';

test('createInvoice creates an invoice with valid input', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].unitPrice, 8500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID to uppercase', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with whitespace', () => {
  const result = createInvoice({
    customerId: ' C-001 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with mixed case and whitespace', () => {
  const result = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice defaults to NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2026-10-31');
});

test('createInvoice fails on invalid terms', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
      terms: 'NET60',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );
});

test('createInvoice EOM on end of month', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2026-01-31');
});

test('createInvoice EOM handles December', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2026-12-31');
});

test('applyVoucher applies a voucher to a draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
  };
  const result = applyVoucher(invoice, { code: 'HOLIDAY10', amount: 10000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'HOLIDAY10');
  assert.equal(result.value.voucher.amount, 10000);
});

test('applyVoucher fails if invoice is not draft', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(
    applyVoucher(invoice, { code: 'HOLIDAY10', amount: 10000 }),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('applyVoucher fails if invoice already has a voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
    voucher: { code: 'EXISTING', amount: 5000 },
  };
  assert.deepEqual(
    applyVoucher(invoice, { code: 'HOLIDAY10', amount: 10000 }),
    { ok: false, error: 'VOUCHER_EXISTS' }
  );
});

test('applyVoucher fails on invalid amount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(
    applyVoucher(invoice, { code: 'HOLIDAY10', amount: 0 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );
  assert.deepEqual(
    applyVoucher(invoice, { code: 'HOLIDAY10', amount: -100 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );
  assert.deepEqual(
    applyVoucher(invoice, { code: 'HOLIDAY10', amount: 100.5 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );
});

test('applyVoucher does not mutate the original invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  applyVoucher(invoice, { code: 'HOLIDAY10', amount: 10000 });
  assert.deepEqual(invoice, invoiceCopy);
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21 }],
    voucher: { code: 'HOLIDAY10', amount: 10000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 17850);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, 92850);
