41	 */
42	export function validateCustomer(c) {
43	  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
44	  return ok({ ...c });
45	}
