47	/**
48	 * Merge two customers, moving all invoices from fromId to intoId.
49	 * @param {Array} customers - Array of customer objects
50	 * @param {Array} invoices - Array of invoice objects
51	 * @param {string} fromId - Customer ID to merge from
52	 * @param {string} intoId - Customer ID to merge into
53	 * @returns {{ ok: true, value: { customers: Array, invoices: Array } } | { ok: false, error: string }}
54	 */
55	export function mergeCustomers(customers, invoices, fromId, intoId) {
56	  const normalizedFromId = normalizeId(fromId);
57	  const normalizedIntoId = normalizeId(intoId);
58	
59	  if (normalizedFromId === normalizedIntoId) {
60	    return fail('SAME_CUSTOMER');
61	  }
62	
63	  const fromCustomer = customers.find((c) => c.id === normalizedFromId);
64	  if (!fromCustomer) {
65	    return fail('CUSTOMER_NOT_FOUND');
66	  }
67	
68	  const intoCustomer = customers.find((c) => c.id === normalizedIntoId);
69	  if (!intoCustomer) {
70	    return fail('CUSTOMER_NOT_FOUND');
71	  }
72	
73	  const newCustomers = customers.filter((c) => c.id !== normalizedFromId);
74	  const newInvoices = invoices.map((inv) => {
75	    if (inv.customerId === normalizedFromId) {
76	      return { ...inv, customerId: normalizedIntoId };
77	    }
78	    return inv;
79	  });
80	
81	  return ok({ customers: newCustomers, invoices: newInvoices });
82	}
