9	
10	function validateDiscount(discountPercent) {
11	  if (discountPercent === undefined || discountPercent === null) return true;
12	  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
13	}
14	
15	function calculateDueDate(issueDate, terms) {
16	  if (terms === 'NET14') return addDays(issueDate, 14);
17	  if (terms === 'NET30') return addDays(issueDate, 30);
18	  if (terms === 'EOM') {
19	    const [year, month] = issueDate.split('-');
20	    const monthNum = Number(month);
21	    const nextMonthNum = monthNum === 12 ? 1 : monthNum + 1;
22	    const nextYear = monthNum === 12 ? Number(year) + 1 : year;
23	    const nextMonth = String(nextMonthNum).padStart(2, '0');
24	    const firstOfNextMonth = `${nextYear}-${nextMonth}-01`;
25	    return addDays(firstOfNextMonth, -1);
26	  }
27	  return null;
28	}
29	
30	/**
31	 * Create an invoice.
32	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
33	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
34	 */
35	export function createInvoice({ customerId, issueDate, lines, terms }) {
36	  // Default terms to NET30
37	  const finalTerms = terms ?? 'NET30';
38	
39	  // Validate terms
40	  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) {
41	    return fail('TERMS_INVALID');
42	  }
43	
44	  // Normalize customer ID
45	  const normalizedCustomerId = normalizeId(customerId);
46	
47	  // Validate customer exists
48	  const customerResult = getCustomer(normalizedCustomerId);
49	  if (!customerResult.ok) return customerResult;
50	  const customer = customerResult.value;
51	
52	  // Validate date format (YYYY-MM-DD) and that it's a real date
53	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
54	
55	  // Validate lines is not empty
56	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
57	
58	  // Build invoice lines with product details
59	  const invoiceLines = [];
60	  for (const line of lines) {
61	    // Validate qty
62	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
63	
64	    // Validate discount
65	    if (!validateDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');
66	
67	    // Validate SKU and get product details
68	    const productResult = getProduct(line.sku);
69	    if (!productResult.ok) return productResult;
70	
71	    const product = productResult.value;
72	    const newLine = {
73	      sku: line.sku,
74	      name: product.name,
75	      qty: line.qty,
76	      unitPrice: product.unitPrice,
77	      vatRate: product.vatRate,
78	    };
79	    // Use provided discount, or fall back to tier discount
80	    const discount = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
81	    if (discount !== 0) {
82	      newLine.discountPercent = discount;
83	    }
84	    invoiceLines.push(newLine);
85	  }
86	
87	  const dueDate = calculateDueDate(issueDate, finalTerms);
88	
89	  return ok({
90	    customerId: normalizedCustomerId,
91	    issueDate,
92	    status: 'draft',
93	    terms: finalTerms,
94	    dueDate,
95	    lines: invoiceLines,
96	  });
97	}
