99	/**
100	 * Add a line to an invoice, or increase qty if SKU already exists.
101	 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
102	 * @param {{ sku: string, qty: number, discountPercent?: number }} input
103	 * @returns {{ ok: true, value } | { ok: false, error: string }}
104	 */
105	export function addLine(invoice, { sku, qty, discountPercent }) {
106	  // Check invoice is draft
107	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
108	
109	  // Validate qty
110	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
111	
112	  // Validate discount
113	  if (!validateDiscount(discountPercent)) return fail('DISCOUNT_INVALID');
114	
115	  // Validate SKU and get product details
116	  const productResult = getProduct(sku);
117	  if (!productResult.ok) return productResult;
118	
119	  const product = productResult.value;
120	  const newLines = invoice.lines.map((line) => ({ ...line }));
121	  const existingLine = newLines.find((line) => line.sku === sku);
122	
123	  if (existingLine) {
124	    existingLine.qty += qty;
125	  } else {
126	    const newLine = {
127	      sku,
128	      name: product.name,
129	      qty,
130	      unitPrice: product.unitPrice,
131	      vatRate: product.vatRate,
132	    };
133	    if (discountPercent !== undefined) {
134	      newLine.discountPercent = discountPercent;
135	    }
136	    newLines.push(newLine);
137	  }
138	
139	  return ok({
140	    ...invoice,
141	    lines: newLines,
142	  });
143	}
144	
145	/**
146	 * Remove a line from an invoice by SKU.
147	 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
148	 * @param {string} sku
149	 * @returns {{ ok: true, value } | { ok: false, error: string }}
150	 */
151	export function removeLine(invoice, sku) {
152	  // Check invoice is draft
153	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
154	
155	  // Check SKU exists on invoice
156	  if (!invoice.lines.find((line) => line.sku === sku)) return fail('LINE_NOT_FOUND');
157	
158	  const newLines = invoice.lines.filter((line) => line.sku !== sku);
159	
160	  // Check would not remove last line
161	  if (newLines.length === 0) return fail('NO_LINES');
162	
163	  return ok({
164	    ...invoice,
165	    lines: newLines,
166	  });
167	}
168	
169	/**
170	 * Apply a voucher to an invoice.
171	 * @param {{ status: string, voucher?: object, lines: Array }} invoice
172	 * @param {{ code: string, amount: number }} voucher
173	 * @returns {{ ok: true, value } | { ok: false, error: string }}
174	 */
175	export function applyVoucher(invoice, { code, amount }) {
176	  // Check invoice is draft
177	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
178	
179	  // Check no voucher already applied
180	  if (invoice.voucher) return fail('VOUCHER_EXISTS');
181	
182	  // Validate amount
183	  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');
184	
185	  return ok({
186	    ...invoice,
187	    voucher: { code, amount },
188	  });
189	}
