191	/**
192	 * Issue an invoice, assigning it a number and changing status to 'issued'.
193	 * @param {{ status: string, lines: Array, customerId: string, issueDate: string }} invoice
194	 * @param {string[]} existingNumbers - Array of existing invoice numbers
195	 * @returns {{ ok: true, value } | { ok: false, error: string }}
196	 */
197	export function issueInvoice(invoice, existingNumbers) {
198	  // Check invoice is draft
199	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
200	
201	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
202	
203	  return ok({
204	    ...invoice,
205	    number,
206	    status: 'issued',
207	  });
208	}
