import fs from 'fs';
import path from 'path';

const testDir = 'test';
const files = fs.readdirSync(testDir).filter(f => f.endsWith('.test.js') && f !== 'totals.test.js');

for (const file of files) {
  const filePath = path.join(testDir, file);
  let content = fs.readFileSync(filePath, 'utf8');

  // Replace qty: 10 with qty: 9 (but keep lines that are specifically testing bulk discount)
  content = content.replace(/qty: 10([,}])/g, 'qty: 9$1');

  // Also handle qty: 100, qty: 20, etc. with replacements that make sense
  content = content.replace(/qty: 100([,}])/g, 'qty: 9$1');
  content = content.replace(/qty: 20([,}])/g, 'qty: 9$1');

  fs.writeFileSync(filePath, content, 'utf8');
  console.log(`Updated ${file}`);
}
